<script lang="ts">
 import { calculateWeld } from './lib/welding.mjs';
 let tab=$state('Spawanie'); let lengthM=$state(8), throatMm=$state(4), depositionKgH=$state(2), arcPercent=$state(35), setupMin=$state(20);
 let result=$derived.by(()=>{try{return calculateWeld({lengthM,throatMm,depositionKgH,arcFactor:arcPercent/100,setupMin})}catch{return null}});
 const tabs=['Nowa wycena','Wyniki','Spawanie','Podgląd 3D','Ustawienia'];
 const fmt=(n:number)=>n.toLocaleString('pl-PL',{maximumFractionDigits:2,minimumFractionDigits:2});
</script>
<svelte:head><meta name="theme-color" content="#11151c"/></svelte:head>
<div class="app"><aside><div class="brand"><span class="mark">DS</span><div><b>DS Estimate</b><small>Desktop · 0.2.1</small></div></div><nav>{#each tabs as t}<button class:active={tab===t} onclick={()=>tab=t}>{t}</button>{/each}</nav><div class="bottom">Svelte 5 · Tauri 2<br/>Offline</div></aside><main><header><div><small>PROJEKT / WYCENA</small><h1>{tab}</h1></div><span class="status">● Prototyp</span></header>{#if tab==='Spawanie'}<section class="panel"><h2>Kalkulator czasu spawania</h2><p>Spoiny pachwinowe o równych ramionach. Wyniki szacunkowe.</p><div class="fields"><label>Długość spoin [m]<input type="number" min="0" bind:value={lengthM}/></label><label>Gardziel a [mm]<input type="number" min="0" bind:value={throatMm}/></label><label>Wydajność stapiania [kg/h]<input type="number" min="0.01" step="0.1" bind:value={depositionKgH}/></label><label>Udział czasu łuku [%]<input type="number" min="1" max="100" bind:value={arcPercent}/></label><label>Przygotowanie [min]<input type="number" min="0" bind:value={setupMin}/></label></div></section><div class="stats"><article><small>Masa spoiny</small><strong>{result?fmt(result.massKg):'—'} <em>kg</em></strong></article><article><small>Czas łuku</small><strong>{result?fmt(result.arcMinutes):'—'} <em>min</em></strong></article><article><small>Czas całkowity</small><strong>{result?fmt(result.totalMinutes/60):'—'} <em>h</em></strong></article></div>{:else}<section class="panel empty"><h2>{tab}</h2><p>Moduł w przygotowaniu. Analiza STEP/PDF/DXF/DWG i wykrywanie spoin nie są jeszcze zaimplementowane.</p></section>{/if}<footer>Wyniki wymagają weryfikacji technologicznej.</footer></main></div>
